+#include "margin_container_editor_plugin.h"
+
+#include "editor/scene/canvas_item_editor_plugin.h"
+#include "editor/themes/editor_scale.h"
+
+void MarginContainerEditorPlugin::edit(Object *p_object) {
+	margin_container = Object::cast_to<MarginContainer>(p_object);
+	CanvasItemEditor::get_singleton()->update_viewport();
+}
+
+bool MarginContainerEditorPlugin::handles(Object *p_object) const {
+	return p_object->is_class("MarginContainer");
+}
+
+void MarginContainerEditorPlugin::forward_canvas_draw_over_viewport(Control *p_viewport_control) {
+	if (margin_container == nullptr) {
+		return;
+	}
+
+	bool item_locked = margin_container->has_meta("_edit_lock_");
+
+	Transform2D xform = CanvasItemEditor::get_singleton()->get_canvas_transform() * margin_container->get_screen_transform();
+
+	// TODO: These colors are copied from CanvasItemEditor::_draw_selection.
+	// We may want to unify them somehow.
+	Color border_color = Color(1, 0.6, 0.4, 0.5);
+
+	if (item_locked) {
+		border_color = Color(0.7, 0.7, 0.7, 0.5);
+	}
+
+	int border_width = Math::round(1 * EDSCALE);
+
+	Rect2 rect = margin_container->_edit_get_rect();
+
+	int margin_left = margin_container->get_theme_constant("margin_left");
+	int margin_top = margin_container->get_theme_constant("margin_top");
+	int margin_right = margin_container->get_theme_constant("margin_right");
+	int margin_bottom = margin_container->get_theme_constant("margin_bottom");

